def recolor_prediction(arr, wall_color, patch_rects, core_top_left):
    H=len(arr); W=len(arr[0]); patches={}; counts=Counter()
    for name,(r0,r1,c0,c1) in patch_rects.items():
        coords=[(r,c) for r in range(r0,r1) for c in range(c0,c1) if arr[r][c]!=wall_color and arr[r][c] not in (3,0,9) ] # don't use this generic bg filtering? 
        patches[name]=coords
        counts.update(arr[r][c] for r,c in coords)
    # patch mode per block
    modes={k:Counter(arr[r][c] for r,c in coords).most_common(1)[0][0] for k,coords in patches.items()}
    global_color=counts.most_common(1)[0][0]
    cr,cc=core_top_left; core={(r,c) for r in range(cr,cr+3) for c in range(cc,cc+3)}
    out=[row[:] for row in arr]
    for r in range(H):
      for c in range(W):
        if arr[r][c]==wall_color:
         if (r,c)==(cr+1,cc+1):out[r][c]=global_color
         elif (r,c) in core:out[r][c]=wall_color
         else:
          ds={k:min(abs(r-a)+abs(c-b) for a,b in pts) for k,pts in patches.items()}
          m=min(ds.values()); tied=[k for k,d in ds.items() if d==m]
          labels={modes[k] for k in tied}
          out[r][c]=next(iter(labels)) if len(labels)==1 else global_color
    return out,patches,modes,global_color
