def pred_from_rects(arr,wall_color,rects,core):
  patches={k:[(r,c) for r in range(r0,r1) for c in range(c0,c1)] for k,(r0,r1,c0,c1) in rects.items()}
  # all bounds intended to be filled patches (no wall) so use all cells
  modes={k:Counter(arr[r][c] for r,c in pts).most_common(1)[0][0] for k,pts in patches.items()}
  tally=Counter(arr[r][c] for pts in patches.values() for r,c in pts)
  g=tally.most_common(1)[0][0]
  out=[row[:] for row in arr]
  cr,cc=core; core_cells={(r,c) for r in range(cr,cr+3) for c in range(cc,cc+3)}
  for r in range(len(arr)):
   for c in range(len(arr[0])):
    if arr[r][c]==wall_color:
     if (r,c)==(cr+1,cc+1): out[r][c]=g
     elif (r,c) in core_cells: out[r][c]=wall_color
     else:
      ds={k:min(abs(r-a)+abs(c-b) for a,b in pts) for k,pts in patches.items()}
      dmin=min(ds.values()); ks=[k for k,d in ds.items() if d==dmin]
      labels={modes[k] for k in ks}
      out[r][c]=next(iter(labels)) if len(labels)==1 else g
  return out,modes,g
